import { randomBytes } from "node:crypto"
import { getAddress, toHex } from "viem"
import { privateKeyToAccount, type PrivateKeyAccount } from "viem/accounts"
import { readAgentWallet } from "@/lib/agent-wallet/cookie"
import { isSealingConfigured, readCookie, sealFor, unsealFor, type CookieWrite } from "@/lib/connections/sealed-cookie"
import { browserIdCookie, isBrowserId, newBrowserId, readBrowserId } from "@/lib/identity/browser-id"
import { isEvmAddress } from "@/lib/rails/arc/constants"

// The agents' wallet of one browser on Arc testnet: a secp256k1 key generated by the server on
// first use and kept ONLY in its own sealed httpOnly cookie (AES-256-GCM, purpose
// "agent-wallet:arc", so it can never be opened as the Solana wallet or the other way round).
// It is a separate random key, never derived from the Solana seed. Same rules as the Solana
// wallet (lib/agent-wallet/cookie.ts): the browser holds ciphertext only, the server keeps no
// copy, and losing the cookie loses what is left in it (testnet only).

export const ARC_AGENT_WALLET_COOKIE = "ac_agent_wallet_arc"
export const ARC_AGENT_WALLET_MAX_AGE = 365 * 24 * 60 * 60
const PURPOSE = "agent-wallet:arc" as const

type SealedArcWallet = { v: 2; chain: "arc"; uid: string; key: string; address: string; createdAt: string }

export type ArcAgentWalletRecord = {
  uid: string
  /** 32-byte secp256k1 private key, 0x hex. Server memory only. */
  key: `0x${string}`
  address: `0x${string}`
  createdAt: string
}

const PRIVATE_KEY = /^0x[0-9a-f]{64}$/

export function createArcAgentWallet(uid: string, options: { random?: (size: number) => Buffer; now?: Date } = {}): ArcAgentWalletRecord {
  // A zero or out-of-range scalar is astronomically unlikely; privateKeyToAccount throws on it.
  const key = toHex(new Uint8Array((options.random ?? randomBytes)(32))) as `0x${string}`
  const account = privateKeyToAccount(key)
  return { uid, key, address: account.address, createdAt: (options.now ?? new Date()).toISOString() }
}

export function arcAgentWalletCookie(record: ArcAgentWalletRecord): CookieWrite {
  const payload: SealedArcWallet = { v: 2, chain: "arc", uid: record.uid, key: record.key, address: record.address, createdAt: record.createdAt }
  return { name: ARC_AGENT_WALLET_COOKIE, value: sealFor(PURPOSE, payload), maxAge: ARC_AGENT_WALLET_MAX_AGE }
}

export function readArcAgentWallet(req: Request): { record: ArcAgentWalletRecord; stale: boolean } | null {
  try {
    const opened = unsealFor<SealedArcWallet>(PURPOSE, readCookie(req, ARC_AGENT_WALLET_COOKIE))
    const value = opened?.value
    if (!opened || !value || value.v !== 2 || value.chain !== "arc" || !isBrowserId(value.uid)) return null
    if (typeof value.key !== "string" || !PRIVATE_KEY.test(value.key) || !isEvmAddress(value.address)) return null
    return {
      record: { uid: value.uid, key: value.key as `0x${string}`, address: getAddress(value.address), createdAt: String(value.createdAt ?? "") },
      stale: opened.stale,
    }
  } catch {
    return null
  }
}

/** The viem account for a wallet record, checked against the address sealed with it. */
export function arcAccountFor(record: ArcAgentWalletRecord): PrivateKeyAccount {
  const account = privateKeyToAccount(record.key)
  if (account.address.toLowerCase() !== record.address.toLowerCase()) throw new Error("The Arc agents' wallet cookie does not match its address.")
  return account
}

export type ResolvedArcAgentWallet = { uid: string; wallet: ArcAgentWalletRecord | null; cookies: CookieWrite[]; created: boolean }

/**
 * This browser's Arc agents' wallet. It belongs to the same browser id as the Solana wallet (so
 * spending caps and approvals stay per browser): an existing Arc wallet keeps its id; a new one
 * takes the Solana wallet's id, then the browser id cookie, then a fresh id.
 */
export function resolveArcAgentWallet(req: Request, options: { create: boolean; refresh?: boolean }): ResolvedArcAgentWallet | null {
  if (!isSealingConfigured()) return null
  const cookies: CookieWrite[] = []
  const existing = readArcAgentWallet(req)
  const browser = readBrowserId(req)
  if (existing) {
    if (existing.stale || options.refresh) cookies.push(arcAgentWalletCookie(existing.record))
    if (!browser) cookies.push(browserIdCookie(existing.record.uid))
    return { uid: existing.record.uid, wallet: existing.record, cookies, created: false }
  }
  const uid = readAgentWallet(req)?.record.uid ?? browser?.id ?? newBrowserId()
  if (!browser || browser.stale || options.refresh) cookies.push(browserIdCookie(uid))
  if (!options.create) return { uid, wallet: null, cookies, created: false }
  const wallet = createArcAgentWallet(uid)
  cookies.push(arcAgentWalletCookie(wallet))
  return { uid, wallet, cookies, created: true }
}
